const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { vendor_name: 'Parse Error', total_amount: 0, confidence: 'low' };
}
const lineItemsSummary = (parsed.line_items || []).map(li => `${li.description}: ${li.quantity}x ${li.unit_price} = ${li.amount}`).join(' | ');
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    vendorName: parsed.vendor_name || '',
    vendorAddress: parsed.vendor_address || '',
    invoiceNumber: parsed.invoice_number || '',
    invoiceDate: parsed.invoice_date || '',
    dueDate: parsed.due_date || '',
    currency: parsed.currency || 'USD',
    subtotal: parsed.subtotal || 0,
    taxAmount: parsed.tax_amount || 0,
    totalAmount: parsed.total_amount || 0,
    paymentTerms: parsed.payment_terms || '',
    lineItems: lineItemsSummary,
    confidence: parsed.confidence || 'unknown',
    notes: parsed.notes || ''
  }
}];
